"use client";

import {
  AnimatePresence,
  motion,
  useAnimate,
  useReducedMotion,
  type Transition,
} from "motion/react";
import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { CartPanel, type OrderState } from "./cart-drawer/cart-panel";
import {
  type CartLine,
  MAX_QUANTITY,
  type Product,
  PRODUCTS,
} from "./cart-drawer/data";
import { type Flight, FlyingItem } from "./cart-drawer/flying-item";
import { ProductCard } from "./cart-drawer/product-card";
import { BagIcon } from "./shared/icons";

// Critically damped: the drawer arrives fast and never overshoots the edge.
const DRAWER: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 41,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Pixels in one rem, read once per measure so the flight is written in rem. */
const remSize = () =>
  Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16;

/**
 * A small Fernhill front desk shop. Adding a product flies its drawing into
 * the cart, and the count changes when it lands. The cart opens as a drawer
 * with quantities, free delivery progress, a promo code and checkout.
 * It is a demo: checkout charges nothing.
 */
export function CartDrawer({ className }: { className?: string }) {
  const titleId = useId();
  const drawerTitleId = useId();
  const reduceMotion = useReducedMotion();
  const [lines, setLines] = useState<CartLine[]>([
    { id: "cards", quantity: 2 },
  ]);
  const [flights, setFlights] = useState<Flight[]>([]);
  const [open, setOpen] = useState(false);
  const [promo, setPromo] = useState(false);
  const [order, setOrder] = useState<OrderState>("open");
  const [notice, setNotice] = useState("");
  const root = useRef<HTMLDivElement | null>(null);
  const cartButton = useRef<HTMLButtonElement | null>(null);
  const flightKey = useRef(0);
  const timer = useRef<number | undefined>(undefined);
  const [badge, animateBadge] = useAnimate<HTMLSpanElement>();
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const count = lines.reduce((sum, line) => sum + line.quantity, 0);

  const land = (productId: string) => {
    setLines((list) =>
      list.some((line) => line.id === productId)
        ? list.map((line) =>
            line.id === productId
              ? { ...line, quantity: Math.min(MAX_QUANTITY, line.quantity + 1) }
              : line,
          )
        : [...list, { id: productId, quantity: 1 }],
    );
    const name =
      PRODUCTS.find((item) => item.id === productId)?.name ?? "Product";
    setNotice(`${name} added to the cart.`);
    if (!reduceMotion && badge.current)
      void animateBadge(
        badge.current,
        { scale: [1, 1.18, 1] },
        { duration: 0.35 },
      );
  };

  const add = (product: Product, art: HTMLElement | null) => {
    if (order === "placed") setOrder("open");
    const box = root.current?.getBoundingClientRect();
    const from = art?.getBoundingClientRect();
    const to = cartButton.current?.getBoundingClientRect();
    if (reduceMotion || !box || !from || !to) {
      land(product.id);
      return;
    }
    const rem = remSize();
    flightKey.current += 1;
    setFlights((list) => [
      ...list,
      {
        key: flightKey.current,
        productId: product.id,
        art: product.art,
        left: (from.left - box.left) / rem,
        top: (from.top - box.top) / rem,
        width: from.width / rem,
        height: from.height / rem,
        dx: (to.left + to.width / 2 - (from.left + from.width / 2)) / rem,
        dy: (to.top + to.height / 2 - (from.top + from.height / 2)) / rem,
      },
    ]);
  };

  const close = () => {
    if (order === "placing") return;
    setOpen(false);
    if (order === "placed") {
      setOrder("open");
      setLines([]);
      setPromo(false);
    }
    cartButton.current?.focus();
  };

  const checkout = () => {
    setOrder("placing");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setOrder("placed"), 1400);
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <div ref={root} className="relative min-h-136">
        <div className="flex flex-col gap-4 p-5" inert={open}>
          <header className="flex items-center justify-between gap-3">
            <div className="min-w-0">
              <h2 id={titleId} className="text-lg font-semibold">
                Front desk shop
              </h2>
              <p className="text-sm text-muted-foreground">
                Kit that makes check-in faster at your clinic.
              </p>
            </div>
            <Button
              ref={cartButton}
              type="button"
              variant="outline"
              aria-haspopup="dialog"
              aria-expanded={open}
              onClick={() => setOpen(true)}
            >
              <span ref={badge} className="inline-flex items-center gap-2">
                <BagIcon aria-hidden="true" />
                Cart
                <span className="grid min-w-5 place-items-center rounded-full bg-marketing-blue-surface px-1.5 text-xs font-semibold text-marketing-blue-ink tabular-nums">
                  {count}
                </span>
              </span>
              <span className="sr-only">, {count} items</span>
            </Button>
          </header>
          <div className="grid grid-cols-1 gap-3 @md:grid-cols-2 @3xl:grid-cols-4">
            {PRODUCTS.map((product) => (
              <ProductCard key={product.id} product={product} onAdd={add} />
            ))}
          </div>
          <p aria-live="polite" className="sr-only">
            {notice}
          </p>
        </div>

        {flights.map((flight) => (
          <FlyingItem
            key={flight.key}
            flight={flight}
            onLand={() => {
              setFlights((list) =>
                list.filter((item) => item.key !== flight.key),
              );
              land(flight.productId);
            }}
          />
        ))}

        <AnimatePresence>
          {open ? (
            <motion.div
              key="scrim"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              transition={reduceMotion ? INSTANT : { duration: 0.2 }}
              onClick={close}
              className="absolute inset-0 z-40 bg-background/60 backdrop-blur-sm"
            />
          ) : null}
          {open ? (
            <motion.div
              key="drawer"
              role="dialog"
              aria-modal="true"
              aria-labelledby={drawerTitleId}
              initial={{ x: "100%" }}
              animate={{ x: 0 }}
              exit={{ x: "100%" }}
              transition={reduceMotion ? INSTANT : DRAWER}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  event.stopPropagation();
                  close();
                }
              }}
              className="absolute inset-y-0 right-0 z-50 w-full max-w-sm border-l border-border bg-card shadow-xl"
            >
              <CartPanel
                titleId={drawerTitleId}
                lines={lines}
                promo={promo}
                order={order}
                onQuantity={(id, quantity) =>
                  setLines((list) =>
                    list.map((line) =>
                      line.id === id ? { ...line, quantity } : line,
                    ),
                  )
                }
                onRemove={(id) =>
                  setLines((list) => list.filter((line) => line.id !== id))
                }
                onPromo={setPromo}
                onCheckout={checkout}
                onClose={close}
              />
            </motion.div>
          ) : null}
        </AnimatePresence>
      </div>
    </BlockFrame>
  );
}

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import { type KeyboardEvent, useEffect, useRef } from "react";

import { CircleCheckIcon, XIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";

import { LoaderIcon, TruckIcon } from "../shared/icons";
import { formatCents } from "../shared/money";
import { PromoField } from "../shared/promo-field";
import { Reveal } from "../shared/reveal";
import {
  type CartLine,
  FREE_DELIVERY,
  priceCart,
  PRODUCTS,
  PROMO,
} from "./data";
import { CartLineRow } from "./cart-line-row";

const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const FILL: Transition = {
  type: "spring",
  stiffness: 300,
  damping: 34,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Where the order stands. */
export type OrderState = "open" | "placing" | "placed";

/** Props for the cart drawer's contents. */
export interface CartPanelProps {
  titleId: string;
  lines: CartLine[];
  promo: boolean;
  order: OrderState;
  onQuantity: (id: string, quantity: number) => void;
  onRemove: (id: string) => void;
  onPromo: (on: boolean) => void;
  onCheckout: () => void;
  onClose: () => void;
}

/**
 * The cart inside the drawer: each line with its quantity, progress toward
 * free delivery, a promo code, the totals and a checkout button. Tab stays
 * inside the drawer while it is open.
 */
export function CartPanel({
  titleId,
  lines,
  promo,
  order,
  onQuantity,
  onRemove,
  onPromo,
  onCheckout,
  onClose,
}: CartPanelProps) {
  const reduceMotion = useReducedMotion();
  const panel = useRef<HTMLDivElement | null>(null);
  const close = useRef<HTMLButtonElement | null>(null);
  const money = priceCart(lines, promo);
  const toGo = Math.max(0, FREE_DELIVERY - money.subtotal);
  const placing = order === "placing";

  const keepShopping = useRef<HTMLButtonElement | null>(null);

  useEffect(() => close.current?.focus(), []);
  // The placed message replaces the button that had focus, so focus moves to its own button.
  useEffect(() => {
    if (order === "placed") keepShopping.current?.focus();
  }, [order]);

  // Keep Tab inside the drawer: past the last control it wraps to the first.
  const trap = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== "Tab" || !panel.current) return;
    const items = [
      ...panel.current.querySelectorAll<HTMLElement>(
        "button:not([disabled]), input:not([disabled]), [tabindex='0']",
      ),
    ];
    const first = items[0];
    const last = items[items.length - 1];
    if (!first || !last) return;
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault();
      first.focus();
    }
  };

  return (
    <div ref={panel} onKeyDown={trap} className="flex h-full flex-col">
      <header className="flex items-center justify-between gap-3 border-b border-border px-4 py-3">
        <h3 id={titleId} className="text-base font-semibold">
          Your cart
        </h3>
        <Button
          ref={close}
          type="button"
          variant="ghost"
          size="icon"
          aria-label="Close the cart"
          disabled={placing}
          onClick={onClose}
        >
          <XIcon aria-hidden="true" />
        </Button>
      </header>

      {order === "placed" ? (
        <div
          className="flex flex-1 flex-col items-center justify-center gap-3 p-6 text-center"
          role="status"
        >
          <CircleCheckIcon
            aria-hidden="true"
            className="size-10 text-marketing-green-ink"
          />
          <p className="font-semibold">Order FH-5521 placed</p>
          <p className="text-sm text-muted-foreground">
            It ships tomorrow to Harbour Street Clinic. A receipt is on its way.
          </p>
          <Button
            ref={keepShopping}
            type="button"
            variant="outline"
            onClick={onClose}
          >
            Keep shopping
          </Button>
        </div>
      ) : (
        <>
          <div className="scroll-fade-effect-y scrollbar-none flex-1 overflow-y-auto px-4">
            <div className="flex flex-col gap-2 py-3">
              <p className="flex items-center gap-2 text-sm">
                <TruckIcon aria-hidden="true" className="size-4 text-chart-2" />
                {toGo > 0
                  ? `Add ${formatCents(toGo)} more for free delivery.`
                  : "Delivery is free on this order."}
              </p>
              <span
                role="progressbar"
                aria-label="Progress toward free delivery"
                aria-valuemin={0}
                aria-valuemax={FREE_DELIVERY}
                aria-valuenow={Math.min(
                  FREE_DELIVERY,
                  Math.round(money.subtotal),
                )}
                className="h-1.5 overflow-hidden rounded-full bg-muted"
              >
                <motion.span
                  initial={false}
                  animate={{
                    scaleX: Math.min(1, money.subtotal / FREE_DELIVERY),
                  }}
                  transition={reduceMotion ? INSTANT : FILL}
                  className="block h-full origin-left rounded-full bg-chart-2"
                />
              </span>
            </div>
            <ul
              aria-label="Products in the cart"
              className="flex flex-col divide-y divide-border"
            >
              <AnimatePresence initial={false}>
                {lines.map((line) => {
                  const product = PRODUCTS.find((item) => item.id === line.id);
                  if (!product) return null;
                  return (
                    <motion.li
                      key={line.id}
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: "auto", opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={reduceMotion ? INSTANT : HEIGHT}
                      className="overflow-hidden"
                    >
                      <CartLineRow
                        product={product}
                        quantity={line.quantity}
                        disabled={placing}
                        onQuantity={(quantity) => onQuantity(line.id, quantity)}
                        onRemove={() => onRemove(line.id)}
                      />
                    </motion.li>
                  );
                })}
              </AnimatePresence>
            </ul>
            {lines.length === 0 ? (
              <p className="py-8 text-center text-sm text-muted-foreground">
                The cart is empty.
              </p>
            ) : null}
          </div>

          <div className="flex flex-col gap-3 border-t border-border p-4">
            <PromoField
              applied={promo ? PROMO.code : null}
              hint={`Try ${PROMO.code}.`}
              onApply={(typed) => {
                const ok = typed.trim().toUpperCase() === PROMO.code;
                if (ok) onPromo(true);
                return ok;
              }}
              onRemove={() => onPromo(false)}
            />
            <dl className="flex flex-col gap-1 text-sm">
              <div className="flex justify-between gap-4">
                <dt className="text-muted-foreground">Subtotal</dt>
                <dd>
                  <RollingText text={formatCents(money.subtotal)} />
                </dd>
              </div>
              <Reveal show={money.discount > 0}>
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">{PROMO.reason}</dt>
                  <dd className="text-marketing-green-ink">
                    <RollingText text={`-${formatCents(money.discount)}`} />
                  </dd>
                </div>
              </Reveal>
              <div className="flex justify-between gap-4">
                <dt className="text-muted-foreground">Delivery</dt>
                <dd>
                  {money.delivery === 0 ? "Free" : formatCents(money.delivery)}
                </dd>
              </div>
              <div className="flex items-baseline justify-between gap-4 pt-1">
                <dt className="font-medium">Total</dt>
                <dd className="text-lg font-semibold">
                  <RollingText text={formatCents(money.total)} />
                </dd>
              </div>
            </dl>
            <Button
              type="button"
              size="lg"
              aria-disabled={placing || lines.length === 0}
              onClick={() => !placing && lines.length > 0 && onCheckout()}
            >
              {placing ? (
                <LoaderIcon
                  aria-hidden="true"
                  className="motion-safe:animate-spin"
                />
              ) : null}
              {placing ? "Placing your order" : "Check out"}
            </Button>
            <p className="text-center text-xs text-muted-foreground">
              Pays with Visa ending 4242 on file.
            </p>
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
