import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";
import type { ReactNode } from "react";

// Critically damped, so a line opens and settles without a bounce.
const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for content that opens and closes its height. */
export interface RevealProps {
  show: boolean;
  children: ReactNode;
  className?: string;
}

/**
 * Opens its content from zero height with a fade and closes it the same way,
 * so the lines under it glide instead of jumping. Reduced motion shows and
 * hides it at once.
 */
export function Reveal({ show, children, className }: RevealProps) {
  const reduceMotion = useReducedMotion();
  const transition = reduceMotion ? INSTANT : HEIGHT;
  return (
    <AnimatePresence initial={false}>
      {show ? (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: "auto", opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          transition={transition}
          className="overflow-hidden"
        >
          <div className={className}>{children}</div>
        </motion.div>
      ) : null}
    </AnimatePresence>
  );
}

/** The drawings the shop has, one for each product. */
export type ArtKind = "stand" | "clock" | "cards" | "signs";

/** A product in the Fernhill front desk shop. */
export interface Product {
  id: string;
  name: string;
  detail: string;
  price: number;
  art: ArtKind;
}

/** The products, in shelf order. */
export const PRODUCTS: Product[] = [
  {
    id: "stand",
    name: "Check-in tablet stand",
    detail: "Swivel base, fits 11 inch tablets",
    price: 89,
    art: "stand",
  },
  {
    id: "clock",
    name: "Queue clock",
    detail: "Wall clock that shows the next patient",
    price: 64,
    art: "clock",
  },
  {
    id: "cards",
    name: "Appointment cards",
    detail: "500 cards printed with your clinic",
    price: 24,
    art: "cards",
  },
  {
    id: "signs",
    name: "Room sign set",
    detail: "Six door signs with booking codes",
    price: 38,
    art: "signs",
  },
];

/** Orders at or over this amount ship free. */
export const FREE_DELIVERY = 120;

/** What delivery costs below the free amount. */
export const DELIVERY_PRICE = 9;

/** The one code the demo accepts. */
export const PROMO = {
  code: "FERN10",
  share: 0.1,
  reason: "Front desk week, 10% off",
};

/** The most of one product a cart holds. */
export const MAX_QUANTITY = 20;

/** One product in the cart and how many. */
export interface CartLine {
  id: string;
  quantity: number;
}

/** The money side of a cart. */
export function priceCart(lines: CartLine[], promo: boolean) {
  const subtotal = lines.reduce(
    (sum, line) =>
      sum +
      (PRODUCTS.find((item) => item.id === line.id)?.price ?? 0) *
        line.quantity,
    0,
  );
  const discount = promo ? subtotal * PROMO.share : 0;
  const delivery =
    subtotal === 0 || subtotal >= FREE_DELIVERY ? 0 : DELIVERY_PRICE;
  return {
    subtotal,
    discount,
    delivery,
    total: subtotal - discount + delivery,
  };
}

