import type { KeyboardEvent } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatCount } from "./money";
import { MinusIcon } from "./icons";

/** Props for a count with minus and plus buttons. */
export interface StepperProps {
  value: number;
  onValueChange: (value: number) => void;
  min: number;
  max: number;
  /** Names the count, such as "Seats". */
  label: string;
  /** How far Page Up and Page Down move. */
  pageStep?: number;
  /** Spoken with the count, such as "seats". */
  unit?: string;
  className?: string;
}

/**
 * A count between two limits. The minus and plus buttons step by one, and the
 * count itself is a spin button: arrows step by one, Page keys by more, Home
 * and End go to the limits. The digits roll as the count changes.
 */
export function Stepper({
  value,
  onValueChange,
  min,
  max,
  label,
  pageStep = 5,
  unit,
  className,
}: StepperProps) {
  const set = (next: number) =>
    onValueChange(Math.min(max, Math.max(min, next)));

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const moves = new Map([
      ["ArrowUp", value + 1],
      ["ArrowRight", value + 1],
      ["ArrowDown", value - 1],
      ["ArrowLeft", value - 1],
      ["PageUp", value + pageStep],
      ["PageDown", value - pageStep],
      ["Home", min],
      ["End", max],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    set(next);
  };

  return (
    <div
      className={cn(
        "inline-flex items-center gap-1 rounded-full border border-border bg-background p-1",
        className,
      )}
    >
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label={`Remove one from ${label.toLowerCase()}`}
        disabled={value <= min}
        onClick={() => set(value - 1)}
      >
        <MinusIcon aria-hidden="true" />
      </Button>
      <div
        role="spinbutton"
        tabIndex={0}
        aria-label={label}
        aria-valuenow={value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={unit ? `${formatCount(value)} ${unit}` : undefined}
        onKeyDown={onKeyDown}
        className="flex min-w-10 cursor-default justify-center rounded-md px-1 text-base font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <RollingText text={formatCount(value)} />
      </div>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label={`Add one to ${label.toLowerCase()}`}
        disabled={value >= max}
        onClick={() => set(value + 1)}
      >
        <PlusIcon aria-hidden="true" />
      </Button>
    </div>
  );
}

"use client";

import type { CSSProperties } from "react";
import { motion } from "motion/react";

import type { ArtKind } from "./data";
import { ProductArt } from "./product-art";

/** One product on its way to the cart, with its start box and end point inside the block, in rem. */
export interface Flight {
  key: number;
  productId: string;
  art: ArtKind;
  left: number;
  top: number;
  width: number;
  height: number;
  /** How far the drawing travels to reach the cart button's centre. */
  dx: number;
  dy: number;
}

/**
 * A copy of a product drawing that flies along an arc into the cart,
 * shrinking and tilting as it goes. `onLand` runs when it arrives.
 */
export function FlyingItem({
  flight,
  onLand,
}: {
  flight: Flight;
  onLand: () => void;
}) {
  // The arc rises above the higher of the two ends before it drops into the cart.
  const lift = Math.min(0, flight.dy) - 3;
  return (
    <motion.div
      aria-hidden="true"
      className="pointer-events-none absolute top-(--fly-top) left-(--fly-left) z-30 h-(--fly-height) w-(--fly-width)"
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          "--fly-left": `${flight.left}rem`,
          "--fly-top": `${flight.top}rem`,
          "--fly-width": `${flight.width}rem`,
          "--fly-height": `${flight.height}rem`,
        } as CSSProperties
      }
      initial={{ x: "0rem", y: "0rem", scale: 1, rotate: 0, opacity: 1 }}
      animate={{
        x: ["0rem", `${flight.dx * 0.45}rem`, `${flight.dx}rem`],
        y: ["0rem", `${lift}rem`, `${flight.dy}rem`],
        scale: [1, 0.55, 0.15],
        rotate: [0, -10, -24],
        opacity: [1, 1, 0.7],
      }}
      transition={{
        duration: 0.75,
        times: [0, 0.45, 1],
        ease: ["easeOut", "easeIn"],
      }}
      onAnimationComplete={onLand}
    >
      <ProductArt kind={flight.art} className="size-full" />
    </motion.div>
  );
}

